-- Append `child` to `parent` (same zone only).
txAddChild :: Word64 -> Word64 -> Builder
txAddChild parent child = wireRecord txKindAddChild (word64LE parent <> word64LE child)

-- Mount a root into a window (0 = the default window).
txMount :: Word64 -> Word64 -> Builder
